202		}
203		if m, err := s.Destroy(DestructionRequest{
204			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
205		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
206			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
207		}
208		if m, err := s.Destroy(DestructionRequest{
209			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
210		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
